import React from 'react'
import { ConnType } from '@/types'
import g from '@/styles/global.module.less'

export interface ClientIconProps {
    kind: ConnType
    size?: number
    className?: string
    style?: React.CSSProperties
}

export default function ClientIcon({
    kind,
    size = 16,
    className = '',
    style,
}: ClientIconProps) {
    return (
        <span
            className={`${g.clientIcon} ${className}`.trim()}
            style={{
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: size,
                height: size,
                minWidth: size,
                minHeight: size,
                lineHeight: 1,
                verticalAlign: 'middle',
                flexShrink: 0,
                ...style,
            }}
        >
            {renderLogoSvg(kind, size)}
        </span>
    )
}

